49: /**
50:  * Substrings that, in a dispatch to `subagent_type: 'critic'`, mark it as a
51:  * plan critic-gate review. Kept lowercase (text is lowercased before
52:  * matching).
53:  */
54: export const PLAN_CRITIC_TASK_SIGNALS = [
55: 	'critic-gate', // "MODE: CRITIC-GATE", "critic-gate protocol/review"
56: 	'plan critic',
57: 	'review plan',
58: 	'review the plan',
59: 	'plan.md', // critic-gate/SKILL.md: "Send the full plan.md content"
60: 	'approve the plan',
61: 	'plan approval',
62: 	// Issue #2012: realistic architect phrasings that the original 7 signals
63: 	// silently missed, wedging the ratchet-tighter critic_pre_plan gate with
64: 	// no recovery. These are safe to add: the caller already narrows to
65: 	// `subagent_type === 'critic'` (a target the trusted architect controls),
66: 	// so a false positive is low-risk, while a false negative silently blocks
67: 	// ALL EXECUTE-phase coder work with no auto-recovery.
68: 	'pre-implementation review',
69: 	'evaluate this plan',
70: 	'evaluate the plan',
71: 	'assess this plan',
72: 	'assess the plan',
73: 	'plan soundness',
74: 	'before implementation',
75: 	'review the plan below',
76: ] as const;
77: 
78: export function taskLooksLikePlanCritic(
79: 	args: Record<string, unknown>,
80: ): boolean {
81: 	const text = [
82: 		args.prompt,
83: 		args.task,
84: 		args.description,
85: 		args.message,
86: 		args.input,
87: 	]
88: 		.filter((value): value is string => typeof value === 'string')
89: 		.join('\n')
90: 		.toLowerCase();
91: 	if (!text) return false;
92: 	// Broad-recall-biased on purpose: the caller already narrows to
93: 	// `subagent_type === 'critic'` (a target the trusted architect controls), so
94: 	// a false positive is low-risk, while a false negative silently blocks ALL
95: 	// EXECUTE-phase coder work with no auto-recovery. Any single signal below —
96: 	// drawn from the phrasings the critic-gate/plan skills tell the architect to
97: 	// send — is therefore sufficient; no AND-pairing.
98: 	return PLAN_CRITIC_TASK_SIGNALS.some((signal) => text.includes(signal));
99: }
