101: function outputText(output: unknown): string {
102: 	if (typeof output === 'string') return output;
103: 	if (typeof output === 'number' || typeof output === 'boolean') {
104: 		return String(output);
105: 	}
106: 	if (Array.isArray(output)) {
107: 		return output.map(outputText).filter(Boolean).join('\n');
108: 	}
109: 	if (output && typeof output === 'object') {
110: 		const record = output as Record<string, unknown>;
111: 		const preferred = ['output', 'text', 'content', 'message', 'result'];
112: 		const parts: string[] = [];
113: 		for (const key of preferred) {
114: 			if (key in record) parts.push(outputText(record[key]));
115: 		}
116: 		if (parts.length > 0) return parts.filter(Boolean).join('\n');
117: 		try {
118: 			return JSON.stringify(output);
119: 		} catch {
120: 			return '';
121: 		}
122: 	}
123: 	return '';
124: }
