126: export function extractPlanCriticVerdict(
127: 	output: unknown,
128: ): 'APPROVED' | 'NEEDS_REVISION' | 'REJECTED' | null {
129: 	const text = outputText(output);
130: 	if (!text) return null;
131: 
132: 	// Primary signal (highest confidence): a `VERDICT: <TOKEN>` line. The critic
133: 	// system prompt (src/agents/critic.ts) instructs this exact shape, so a
134: 	// conforming critic always matches here. Also tolerates markdown-bold labels
135: 	// (`**VERDICT**:`) which LLMs frequently emit despite the plain instruction.
136: 	const primary =
137: 		/^\s*(?:\*\*)?VERDICT(?:\*\*)?\s*:\s*(APPROVED|NEEDS_REVISION|REJECTED)\b/im.exec(
138: 			text,
139: 		);
140: 	if (primary) {
141: 		return primary[1].toUpperCase() as
142: 			| 'APPROVED'
143: 			| 'NEEDS_REVISION'
144: 			| 'REJECTED';
145: 	}
146: 
147: 	// Fallback 1: a `## Verdict` (or `### Verdict`, …) heading followed (within
148: 	// 2 lines) by a line whose only non-whitespace content is the verdict token.
149: 	// Matches critics that emit the verdict under a markdown heading instead of
150: 	// the `VERDICT:` label. The heading must be the verdict section specifically
151: 	// (not e.g. `## PLAN REVIEW`), so the `Verdict` word is required.
152: 	const heading = /^(#{1,6})\s*Verdict\s*$/im.exec(text);
153: 	if (heading && heading.index !== undefined) {
154: 		const after = text.slice(heading.index + heading[0].length);
155: 		const nextLines = after.split('\n').slice(0, 3).join('\n');
156: 		const headingMatch = /^\s*(APPROVED|NEEDS_REVISION|REJECTED)\s*$/im.exec(
157: 			nextLines,
158: 		);
159: 		if (headingMatch) {
160: 			return headingMatch[1].toUpperCase() as
161: 				| 'APPROVED'
162: 				| 'NEEDS_REVISION'
163: 				| 'REJECTED';
164: 		}
165: 	}
166: 
167: 	// Fallback 2: a BARE verdict token on its own line — but ONLY in the final
168: 	// few lines of output (so a mid-review mention like "this is approved for
169: 	// execution" cannot trigger it) and ONLY when the line does not contain a
170: 	// `|` separator (which marks the critic-rubric template line
171: 	// `VERDICT: APPROVED | NEEDS_REVISION | REJECTED`, an enumeration rather
172: 	// than a real verdict) and is not inside a fenced code block.
173: 	//
174: 	// Issue #2012: real critics do not always emit the `VERDICT:` label, and a
175: 	// missing snapshot here permanently wedges every coder delegation because
176: 	// the gate is ratchet-tighter with no escape hatch. The tail-only + no-pipe
177: 	// + no-code-fence guards keep false positives out while recovering the
178: 	// common "the critic just wrote APPROVED at the end" case.
179: 	const lines = text.split('\n');
180: 	const tailStart = Math.max(0, lines.length - 6);
181: 	let inFence = false;
182: 	for (let i = 0; i < lines.length; i++) {
183: 		// Match 3+ backticks so a 4-backtick fenced block (common for nested
184: 		// code blocks) also toggles the fence state, not just exactly ```.
185: 		// The regex is "3 or more backtick characters" — the {3,} quantifier
186: 		// applies to the single preceding backtick literal.
187: 		if (/^\s*(?:`{3,})/.test(lines[i])) inFence = !inFence;
188: 		if (i < tailStart) continue;
189: 		if (inFence) continue;
190: 		const line = lines[i];
191: 		if (line.includes('|')) continue;
192: 		const bare = /^\s*(APPROVED|NEEDS_REVISION|REJECTED)\s*$/i.exec(line);
193: 		if (bare) {
194: 			return bare[1].toUpperCase() as
195: 				| 'APPROVED'
196: 				| 'NEEDS_REVISION'
197: 				| 'REJECTED';
198: 		}
199: 	}
200: 
201: 	return null;
202: }
