204: /** Which Task transport produced the approval request (audit metadata). */
205: export type PlanCriticApprovalTransport = 'sync_task' | 'async_completion';
206: 
207: export interface PlanCriticApprovalRequest {
208: 	/** Dispatching (parent) session id — embedded in the approval audit. */
209: 	parentSessionId: string;
210: 	/** Tool call id of the critic dispatch — the replay-dedup key. */
211: 	callId: string;
212: 	/**
213: 	 * The critic child's result text. Callers must have established that this
214: 	 * text is the host-verified terminal result of the critic child bound to
215: 	 * `(parentSessionId, callId)` — never raw model text from an unverified
216: 	 * source.
217: 	 */
218: 	verdictText: unknown;
219: 	/**
220: 	 * Structural hash of the plan captured at DISPATCH time and persisted on
221: 	 * the delegation record (async transport). When present, the current plan
222: 	 * must still match it; a plan edited after the dispatch cannot be approved
223: 	 * by the old verdict.
224: 	 */
225: 	dispatchPlanStructureHash?: string;
226: 	transport: PlanCriticApprovalTransport;
227: }
228: 
229: export type PlanCriticApprovalRecording =
230: 	| { outcome: 'recorded'; planId: string }
231: 	/** The verdict is not an approval (or absent) — nothing to record. */
232: 	| { outcome: 'not_approved'; reason: string }
233: 	/** A verified approval exists already (replay) or the plan changed. */
234: 	| { outcome: 'skipped'; reason: string }
235: 	/** The approval could not be persisted; the gate stays blocked. */
236: 	| { outcome: 'failed'; reason: string };
237: 
238: /**
239:  * Whether the ledger already carries a `plan_critic_gate` approval snapshot
240:  * bound to the exact `callId` (verified-prefix scan; a quarantined suffix is
241:  * never trusted — see #2531). This is the durable replay fence: a terminal
242:  * event may be delivered more than once (duplicate completion, crash
243:  * recovery, maintenance replay), but it can only ever approve once.
244:  */
245: export async function hasPlanCriticApprovalSnapshotForCall(
246: 	directory: string,
247: 	callId: string,
248: ): Promise<boolean> {
249: 	if (!callId) return false;
250: 	try {
251: 		const integrity = await readLedgerEventsWithIntegrity(directory);
252: 		for (let i = integrity.events.length - 1; i >= 0; i--) {
253: 			const event = integrity.events[i];
254: 			if (event.event_type !== 'snapshot') continue;
255: 			if (event.source !== 'critic_approved') continue;
256: 			const payload = event.payload as
257: 				| (Record<string, unknown> & {
258: 						approval?: Record<string, unknown>;
259: 				  })
260: 				| undefined;
261: 			if (payload?.approval?.source !== 'plan_critic_gate') continue;
262: 			if (payload.approval.call_id === callId) return true;
263: 		}
264: 		return false;
265: 	} catch (error) {
266: 		// An unreadable ledger cannot PROVE the absence of a prior approval.
267: 		// Fail closed: report "already present" so the caller skips the write
268: 		// rather than risking a duplicate approval after a partial crash. The
269: 		// caller surfaces this as a skipped recording with the read error.
270: 		warn(
271: 			`[plan-critic-approval] ledger read failed while checking for prior approval of call ${callId}: ${
272: 				error instanceof Error ? error.message : String(error)
273: 			}`,
274: 		);
275: 		return true;
276: 	}
277: }
278: 
279: /**
280:  * Record the plan-critic approval snapshot for a verified critic child
281:  * completion. See the module docstring for the full safety contract. Never
282:  * throws — every failure is a typed outcome so both transports can surface it
283:  * without breaking their own error containment.
284:  */
285: export async function recordVerifiedPlanCriticApproval(
286: 	directory: string,
287: 	request: PlanCriticApprovalRequest,
288: ): Promise<PlanCriticApprovalRecording> {
289: 	if (extractPlanCriticVerdict(request.verdictText) !== 'APPROVED') {
290: 		return { outcome: 'not_approved', reason: 'verdict is not APPROVED' };
291: 	}
292: 
293: 	// Issue #2012: a critic APPROVED verdict that fails to record a snapshot
294: 	// permanently wedges the ratchet-tighter critic_pre_plan gate (no escape
295: 	// hatch). loadPlanJsonOnly can transiently return null if the critic
296: 	// dispatch landed microseconds before a concurrent save_plan flush. The
297: 	// architect skill ordering (save_plan → CRITIC-GATE) is the primary
298: 	// guarantee; this bounded retry is cheap insurance against the race so a
299: 	// legitimate APPROVED is not silently dropped. Keep attempts tiny — the
300: 	// common path resolves on the first read.
301: 	let plan: Plan | null = await loadPlanJsonOnly(directory);
302: 	if (!plan) {
303: 		for (let attempt = 0; attempt < 2 && !plan; attempt++) {
304: 			await new Promise((resolve) => setTimeout(resolve, 150));
305: 			plan = await loadPlanJsonOnly(directory);
306: 		}
307: 	}
308: 	if (!plan) {
309: 		return {
310: 			outcome: 'failed',
311: 			reason: 'plan.json not readable after retry',
312: 		};
313: 	}
314: 
315: 	// Async-transport staleness fence: the critic reviewed the plan as it was
316: 	// at DISPATCH time (hash persisted on the delegation record). If the plan
317: 	// changed since, this APPROVED verdict is stale — it must not approve the
318: 	// edited plan. The architect must re-run the critic (or use the audited
319: 	// manual escape hatch).
320: 	if (
321: 		request.dispatchPlanStructureHash !== undefined &&
322: 		computePlanStructureHash(plan) !== request.dispatchPlanStructureHash
323: 	) {
324: 		return {
325: 			outcome: 'skipped',
326: 			reason:
327: 				'plan structure changed since the critic dispatch — the APPROVED verdict no longer covers the current plan; re-run the critic gate',
328: 		};
329: 	}
330: 
331: 	// Durable replay fence: the exact dispatch (callId) may only ever produce
332: 	// one approval snapshot. Duplicate terminal delivery, crash recovery, and
333: 	// maintenance replays all land here as no-ops.
334: 	if (await hasPlanCriticApprovalSnapshotForCall(directory, request.callId)) {
335: 		return {
336: 			outcome: 'skipped',
337: 			reason: 'an approval snapshot for this dispatch already exists',
338: 		};
339: 	}
340: 
341: 	try {
342: 		// Store the STRUCTURAL hash (status-excluded) as the snapshot's
343: 		// payload_hash so `assertPlanCriticApprovedForExecution` can match this
344: 		// approval after the architect flips the current task to `in_progress`
345: 		// before delegating its coder. This MUST be the same hash function the
346: 		// gate compares against (`computePlanStructureHash`), or the staleness
347: 		// check would never match.
348: 		await takeSnapshotEvent(directory, plan, {
349: 			source: 'critic_approved',
350: 			approvalMetadata: {
351: 				verdict: 'APPROVED',
352: 				source: 'plan_critic_gate',
353: 				session_id: request.parentSessionId,
354: 				call_id: request.callId,
355: 				approved_at: new Date().toISOString(),
356: 				transport: request.transport,
357: 			},
358: 			payloadHashOverride: computePlanStructureHash(plan),
359: 		});
360: 		return { outcome: 'recorded', planId: derivePlanId(plan) };
361: 	} catch (error) {
362: 		log(
363: 			`[plan-critic-approval] snapshot write failed: ${
364: 				error instanceof Error ? error.message : String(error)
365: 			}`,
366: 		);
367: 		return {
368: 			outcome: 'failed',
369: 			reason: error instanceof Error ? error.message : String(error),
370: 		};
371: 	}
372: }

