/**
 * Issue #1151 — Support OpenCode background subagents safely in swarm (PR 1).
 *
 * OpenCode background subagents (`Task` with `background=true`) return a
 * "running" placeholder immediately and complete later via synthetic injection.
 * The default-off compatibility path still fail-closed-blocks background swarm
 * delegations until users opt into the trusted completion/settlement pipeline:
 *   - toolBefore throws (pre-dispatch, fail-closed chain) for swarm roles.
 *   - toolAfter defensively early-returns so a running placeholder never advances
 *     Stage B or records gate evidence.
 *
 * Foreground delegation behavior is unchanged.
 */
import { afterEach, beforeEach, describe, expect, it } from 'bun:test';
import type { PluginConfig } from '../../../src/config';
import {
	createDelegationGateHook,
	SWARM_BACKGROUND_TASK_BLOCKED_MESSAGE,
} from '../../../src/hooks/delegation-gate';
import {
	deleteStoredInputArgs,
	getStoredInputArgs,
	setStoredInputArgs,
} from '../../../src/hooks/guardrails';
import {
	ensureAgentSession,
	getTaskState,
	resetSwarmState,
} from '../../../src/state';
import { createSafeTestDir } from '../../helpers/safe-test-dir';

function makeConfig(): PluginConfig {
	return {
		max_iterations: 5,
		qa_retry_limit: 3,
		inject_phase_reminders: true,
		hooks: {
			system_enhancer: true,
			compaction: true,
			agent_activity: true,
			delegation_tracker: false,
			agent_awareness_max_chars: 300,
			delegation_gate: true,
			delegation_max_chars: 4000,
		},
	} as PluginConfig;
}

async function callToolBefore(
	hook: ReturnType<typeof createDelegationGateHook>,
	args: Record<string, unknown>,
	sessionID = 'bg-session',
): Promise<{ threw: boolean; message: string | null }> {
	try {
		await hook.toolBefore(
			{ tool: 'Task', sessionID, callID: `call-${sessionID}` },
			{ args },
		);
		return { threw: false, message: null };
	} catch (err) {
		return {
			threw: true,
			message: err instanceof Error ? err.message : String(err),
		};
	}
}

describe('issue #1151 — background Task fail-closed guard', () => {
	// A throwaway project dir: process.cwd() is the developer's checkout, so the
	// gate read (and wrote .swarm/session/ into) the repository's own state, and
	// a stray plan left there by another suite changed these results.
	let directory: string;
	let cleanup: () => void;
	beforeEach(() => {
		resetSwarmState();
		({ dir: directory, cleanup } = createSafeTestDir('delegation-gate-bg-'));
	});
	afterEach(() => {
