		contextMap: { enabled: true },
	});
	await observer.event(
		completionEvent('ses_closeout_child', 'completed', COMPLETED_BODY),
	);
	const map = loadContextMap(directory);
	expect(map?.task_history['1.1']).toBeUndefined();
});

