/** Deterministic terminal id — the same helper the live observer uses. */
function terminalEventId(directory: string, status: string, text: string) {
	return buildBackgroundCompletionEventId({
		correlationId: 'ses_recovery_child',
		jobId: 'job-recovery',
		status,
		resultDigest: (() => {
			// Match the observer's digest helper (sha256 of the result text).
			// Imported lazily to keep the module graph out of the describe path.
			const { createHash } = require('node:crypto') as {
				createHash: (a: string) => { update: (b: string) => { digest: (c: string) => string } };
			};
			return createHash('sha256').update(text).digest('hex');
		})(),
	});
}

